const EM_CFG={url:'https://tikjmiyrhkcjrxjylmqb.supabase.co',key:'sb_publishable_clr5P9USk7b63MajJmmr9A_Iz0wi_0F',version:'2026.08.16-evidence-manager1'};
const EM_SESSION='fleet_mvp_session_v2',EM_INCIDENT='fleet_mvp_current_incident',EM_UPLOAD_INCIDENT='fleet_mvp_evidence_incident_v1',EM_PACKAGE='fleet_mvp_current_package';
function emSession(){try{return JSON.parse(localStorage.getItem(EM_SESSION)||'null')}catch{return null}}
function emSave(s){if(s)localStorage.setItem(EM_SESSION,JSON.stringify(s))}
function emIncidentId(){return sessionStorage.getItem(EM_UPLOAD_INCIDENT)||sessionStorage.getItem(EM_INCIDENT)||''}
async function emRefreshSession(){const s=emSession();if(!s?.refresh_token)throw new Error('Сессия истекла. Войдите снова.');const r=await fetch(`${EM_CFG.url}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:EM_CFG.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});const d=await r.json().catch(()=>({}));if(!r.ok||!d.access_token)throw new Error(d.message||d.msg||'Сессия истекла. Войдите снова.');d.obtained_at=Date.now();emSave(d);return d}
async function emRpc(name,params={},retry=true){let s=emSession();if(!s?.access_token)throw new Error('Нужно войти в систему.');let r=await fetch(`${EM_CFG.url}/rest/v1/rpc/${encodeURIComponent(name)}`,{method:'POST',headers:{apikey:EM_CFG.key,Authorization:`Bearer ${s.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(params)});if(r.status===401&&retry){s=await emRefreshSession();return emRpc(name,params,false)}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.message||x.error||x.hint||`HTTP ${r.status}`)}const t=await r.text();return t?JSON.parse(t):null}
async function emBlob(path,retry=true){let s=emSession();if(!s?.access_token)throw new Error('Нужно войти в систему.');const url=`${EM_CFG.url}/storage/v1/object/incident-evidence/${String(path).split('/').map(encodeURIComponent).join('/')}`;let r=await fetch(url,{headers:{apikey:EM_CFG.key,Authorization:`Bearer ${s.access_token}`}});if(r.status===401&&retry){s=await emRefreshSession();return emBlob(path,false)}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.message||x.error||'Не удалось открыть файл.')}return r.blob()}
function emEsc(v=''){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function emDt(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d)}
function emType(v){return v==='pdf'?'PDF':'Фото'}
function emFile(path=''){return String(path||'').split('/').filter(Boolean).pop()?.replace(/^[0-9a-f-]{36}-/i,'')||'Файл'}
function emHash(v=''){const s=String(v||'');return s?`${s.slice(0,12)}…${s.slice(-8)}`:'SHA-256 не сохранён'}
function emToast(text,type=''){let h=document.querySelector('.toast-host');if(!h){h=document.createElement('div');h.className='toast-host';document.body.appendChild(h)}const e=document.createElement('div');e.className=`toast ${type}`;e.textContent=text;h.appendChild(e);setTimeout(()=>e.remove(),3800)}
function emBaseAction(action,data={}){const b=document.createElement('button');b.type='button';b.hidden=true;b.dataset.action=action;Object.entries(data).forEach(([k,v])=>{if(v!==null&&v!==undefined)b.dataset[k]=String(v)});document.body.appendChild(b);b.click();queueMicrotask(()=>b.remove())}
function emRefresh(){emBaseAction('refresh')}
function emActiveRow(x){return `<div class="em-row"><div class="em-file-main"><div class="em-file-title"><span class="badge">${emEsc(emType(x.type))}</span> ${emEsc(emFile(x.storage_path))}</div><div class="em-file-sub">${emEsc(x.description||'Без описания')} · ${emEsc(emDt(x.created_at))}</div><div class="em-hash" title="${emEsc(x.sha256||'')}">${emEsc(emHash(x.sha256))}</div></div><div class="em-actions"><button type="button" class="soft-btn" data-em-open data-path="${emEsc(x.storage_path)}">Открыть</button>${x.can_void?`<button type="button" class="soft-btn em-void" data-em-void data-id="${emEsc(x.id)}">Исключить</button>`:''}</div></div>`}
function emExcludedRow(x){return `<div class="em-row excluded"><div class="em-file-main"><div class="em-file-title"><span class="badge">Исключён</span> ${emEsc(emFile(x.storage_path))}</div><div class="em-file-sub">${emEsc(x.reason||'Причина не указана')} · ${emEsc(emDt(x.voided_at))}</div><div class="em-hash" title="${emEsc(x.sha256||'')}">${emEsc(emHash(x.sha256))}</div></div><div class="em-actions"><button type="button" class="soft-btn" data-em-open data-path="${emEsc(x.storage_path)}">Открыть</button></div></div>`}
function emSection(data,incidentId){const active=data.active||[],excluded=data.excluded||[];const s=document.createElement('section');s.className='section em-section';s.dataset.emSection=EM_CFG.version;s.innerHTML=`<div class="section-head em-head"><div><h2>Подтверждающие материалы</h2><div class="muted small">В пакеты входят только активные материалы.</div></div><div class="em-head-actions"><span class="badge">${active.length}</span>${data.can_add?`<button type="button" class="soft-btn" data-em-add data-incident="${emEsc(incidentId)}">Добавить</button>`:''}</div></div>${!data.can_add?'<div class="alert"><div>✓</div><div><div class="alert-title">Состав зафиксирован</div><div class="alert-sub">Пакет уже сформирован. Добавление и исключение материалов заблокировано.</div></div></div>':''}<div class="em-list">${active.map(emActiveRow).join('')||'<div class="empty">Подтверждающих материалов пока нет.</div>'}</div>${excluded.length?`<details class="em-excluded"><summary>Исключённые материалы · ${excluded.length}</summary><div class="em-list">${excluded.map(emExcludedRow).join('')}</div></details>`:''}`;return s}
async function emDecorate(){const main=document.querySelector('.main');if(!main||main.querySelector('[data-em-section]'))return;const title=document.querySelector('.page-title')?.textContent?.trim()||'';if(title!=='Происшествие'&&!title.startsWith('Материалы '))return;const incidentId=emIncidentId();if(!incidentId)return;let data;try{data=await emRpc('get_incident_evidence_ui',{p_incident_id:incidentId})}catch{return}if(!document.body.contains(main)||main.querySelector('[data-em-section]'))return;const section=emSection(data,incidentId);const actions=main.querySelector('.action-row');if(actions)actions.before(section);else main.appendChild(section)}
async function emOpen(path,button){button.disabled=true;const w=window.open('','_blank');if(!w){button.disabled=false;emToast('Браузер заблокировал окно файла. Разрешите всплывающие окна для этого сайта.','error');return}w.opener=null;try{const blob=await emBlob(path);const url=URL.createObjectURL(blob);w.location.href=url;setTimeout(()=>URL.revokeObjectURL(url),120000)}catch(e){w.close();emToast(e.message||'Не удалось открыть файл.','error')}finally{button.disabled=false}}
async function emVoid(id,button){const prompt=window.fleetUxPrompt;const reason=prompt?await prompt({title:'Исключить материал из пакета?',body:'Файл останется в защищённом хранилище и в журнале аудита, но перестанет входить в текущий пакет. Укажите причину.',label:'Причина исключения',placeholder:'Например: загружен не тот файл',required:true,maxLength:500,confirmLabel:'Исключить',danger:true}):window.prompt('Причина исключения материала:');if(!String(reason||'').trim())return;button.disabled=true;try{await emRpc('void_incident_evidence',{p_evidence_id:id,p_reason:String(reason).trim()});emToast('Материал исключён. Подготовленный пакет, если был, возвращён на сбор данных.','success');emRefresh()}catch(e){const m=String(e.message||'');emToast(/after package formation/i.test(m)?'Пакет уже сформирован — его состав зафиксирован.':m,'error');button.disabled=false}}
document.addEventListener('click',e=>{const add=e.target.closest('[data-em-add]');if(add){e.preventDefault();e.stopImmediatePropagation();sessionStorage.setItem(EM_UPLOAD_INCIDENT,add.dataset.incident||'');emBaseAction('upload-evidence',{incident:add.dataset.incident,package:sessionStorage.getItem(EM_PACKAGE)||''});return}const open=e.target.closest('[data-em-open]');if(open){e.preventDefault();e.stopImmediatePropagation();emOpen(open.dataset.path,open);return}const voidBtn=e.target.closest('[data-em-void]');if(voidBtn){e.preventDefault();e.stopImmediatePropagation();emVoid(voidBtn.dataset.id,voidBtn)}},true);
let emQueued=false;function emSchedule(){if(emQueued)return;emQueued=true;queueMicrotask(()=>{emQueued=false;emDecorate()})}new MutationObserver(emSchedule).observe(document.documentElement,{childList:true,subtree:true});window.addEventListener('fleet:role-ux-ready',emSchedule);emSchedule();